535:   async consultarCargaAcademica(documento: string) {
536:     let parametros = {
537:       parametros: {
538:         identificacion: documento
539:       }
540:     }
541:     let storedConsultaEstudiante = localStorage.getItem('data_evaluacion_estudiante');
542:     if (storedConsultaEstudiante !== null) {
543:       const dataParsed = JSON.parse(storedConsultaEstudiante);
544:       return {
545:         cod_estudiante: dataParsed.Data.estudiante.espacios[0].cod_estudiante, //Valor necesario para el evaluador
546:         identificacion: dataParsed.Data.estudiante.espacios[0].doc_estudiante,
547:         nombre: dataParsed.Data.estudiante.espacios[0].nom_estudiante,
548:         proyectos: this.transformarDatosEstudiante(dataParsed.Data.estudiante.espacios),
549:         proyectosEspc: this.transformarDatosEstudianteEsp(dataParsed.Data.estudiante.espacios)
550:       };
551:     }
552:     else {
553:       return new Promise((resolve, reject) => {
554:         this.evaluacionDocenteMidService
555:           .post('carga_academica', parametros)
556:           .subscribe(
557:             (response: any) => {
558:               if (response.Data != null) {
559:                 localStorage.setItem('data_evaluacion_estudiante', JSON.stringify(response));
560:                 resolve({
561:                   cod_estudiante: response.Data.estudiante.espacios[0].cod_estudiante, //Valor necesario para el evaluador
562:                   identificacion: response.Data.estudiante.espacios[0].doc_estudiante,
563:                   nombre: response.Data.estudiante.espacios[0].nom_estudiante,
564:                   proyectos: this.transformarDatosEstudiante(response.Data.estudiante.espacios),
565:                   proyectosEspc: this.transformarDatosEstudianteEsp(response.Data.estudiante.espacios)
566:                 });
567:               } else {
568:                 resolve(response);
569:               }
570:             },
571:             (error) => {
572:               reject(new Error(`Error al consultar la carga academica: ${error?.message || error}`));
573:             }
574:           );
575:       });
576:     }
577:   }
