579:   transformarDatosEstudiante(lista: any[]): any[] {
580:     const proyectosMap = new Map<number, any>();
581: 
582:     lista.forEach((elemento) => {
583: 
584:       const { cod_proyecto, nom_docente, doc_docente, nom_proyecto, cod_espacio, espacio_academico, grupo } = elemento;
585: 
586:       if (!proyectosMap.has(cod_proyecto)) {
587:         proyectosMap.set(cod_proyecto, {
588:           id: cod_proyecto,
589:           nombre: nom_proyecto,
590:           docentes: [],
591:           asignaturas: []
592:         });
593:       }
594: 
595:       const proyecto = proyectosMap.get(cod_proyecto);
596:       if (proyecto) {
597:         const docenteExistente = proyecto.docentes.some((docente: any) => docente.id === doc_docente);
598:         if (!docenteExistente) {
599:           proyecto.docentes.push({
600:             id: doc_docente,
601:             nombre: nom_docente
602:           });
603:         }
604: 
605:         const asignaturaExistente = proyecto.asignaturas.some((asignatura: any) => asignatura.id === String(cod_espacio));
606:         if (!asignaturaExistente) {
607:           proyecto.asignaturas.push({
608:             id: String(cod_espacio),
609:             nombre: espacio_academico,
610:             grupos: grupo,
611:             docente: doc_docente
612:           });
613:         }
614:       }
615:     });
616: 
617:     return Array.from(proyectosMap.values());
618:   }
