663:   filtrarEspaciosPorProyecto(data: any, codProyecto: Number) {
664:     const espaciosMap = new Map<string, any>();
665: 
666:     for (let i = 0; i < data.docente.carga.length; i++) {
667:       let item = data.docente.carga[i];
668: 
669:       if (item.cod_proyecto == codProyecto) {
670:         let clave = item.cod_proyecto + "-" + item.cod_espacio + "-" + item.espacio;
671: 
672:         if (!espaciosMap.has(clave)) {
673:           // Crear la estructura base con los grupos en un array
674:           espaciosMap.set(clave, {
675:             id: item.cod_espacio,
676:             nombre: item.espacio,
677:             grupos: []
678:           });
679:         }
680: 
681:         // Obtener la referencia del objeto en el mapa y agregar el grupo si aún no está
682:         let entry = espaciosMap.get(clave);
683:         if (!entry.grupos.some((g: any) => g.id_grupo === item.id_grupo)) {
684:           entry.grupos.push({
685:             id_grupo: item.id_grupo,
686:             grupo: item.grupo
687:           });
688:         }
689:       }
690:     }
691: 
692:     return Array.from(espaciosMap.values());
693:   }
